import com.google.gson.GsonBuilder;
import java.util.Date;
public class TestGsonNullDate {
  static class Person { private Date age; }
  public static void main(String[] args) {
    System.out.println(new GsonBuilder().setDateFormat("yyyy-MM-dd").create().toJson(new Person()));
    System.out.println(new GsonBuilder().setDateFormat("yyyy-MM-dd").serializeNulls().create().toJson(new Person()));
  }
}
EOF
